static __inline uint64_t
dwarf_read_uleb128(unsigned char **ln, unsigned char *end)
{
    unsigned char *cp = *ln;
    uint64_t retval = 0;
    int i;
    for (i = 0; i < ((8 * sizeof (int64_t) + 6) / 7); i++) {
	uint64_t byte = ((cp) < (end) ? *(cp)++ : 0);
        retval |= (byte & 0x7f) << (i * 7);
	if ((byte & 0x80) == 0)
	    break;
    }
    *ln = cp;
    return retval;
}
static __inline int64_t
dwarf_read_sleb128(unsigned char **ln, unsigned char *end)
{
    unsigned char *cp = *ln;
    int64_t retval = 0;
    int i;
    for (i = 0; i < ((8 * sizeof (int64_t) + 6) / 7); i++) {
	uint64_t byte = ((cp) < (end) ? *(cp)++ : 0);
        retval |= (byte & 0x7f) << (i * 7);
	if ((byte & 0x80) == 0) {
	    if ((byte & 0x40) && (i + 1) * 7 < 64)
		retval |= (uint64_t)-1LL << ((i + 1) * 7);
	    break;
	}
    }
    *ln = cp;
    return retval;
}
typedef struct { volatile LONG init; CRITICAL_SECTION cs; } TCCSem;
static __inline void wait_sem(TCCSem *p) {
    if (_InterlockedCompareExchange(&p->init, 1, 0) == 0) {
        InitializeCriticalSection(&p->cs);
        _InterlockedExchange(&p->init, 2);
    } else {
        while (_InterlockedCompareExchange(&p->init, 2, 2) != 2)
            Sleep(0);
    }
    EnterCriticalSection(&p->cs);
}
static __inline void post_sem(TCCSem *p) {
    LeaveCriticalSection(&p->cs);
}
