    case 0xc3:
    case 0xc6:
    case 0xc7:
    case 0xc4:
    case 0xc5:
        sprintf(p, "%llu", (unsigned long long)cv->i);
        break;
    case 0xc1:
        cstr_ccat(&cstr_buf, 'L');
    case 0xc0:
        cstr_ccat(&cstr_buf, '\'');
        add_char(&cstr_buf, cv->i);
        cstr_ccat(&cstr_buf, '\'');
        cstr_ccat(&cstr_buf, '\0');
        break;
    case 0xcd:
    case 0xce:
        return (char*)cv->str.data;
    case 0xc9:
        cstr_ccat(&cstr_buf, 'L');
    case 0xc8:
        cstr_ccat(&cstr_buf, '\"');
        if (v == 0xc8) {
            len = cv->str.size - 1;
            for(i=0;i<len;i++)
                add_char(&cstr_buf, ((unsigned char *)cv->str.data)[i]);
        } else {
            len = (cv->str.size / sizeof(nwchar_t)) - 1;
            for(i=0;i<len;i++)
                add_char(&cstr_buf, ((nwchar_t *)cv->str.data)[i]);
        }
        cstr_ccat(&cstr_buf, '\"');
        cstr_ccat(&cstr_buf, '\0');
        break;
