        return strcpy(p, "<float>");
    case 0xcb:
        return strcpy(p, "<double>");
    case 0xcc:
        return strcpy(p, "<long double>");
    case 0xcf:
        return strcpy(p, "<linenumber>");
    case 0x9c:
        v = '<';
        goto addv;
    case 0x9f:
        v = '>';
        goto addv;
    case 0xa1:
