    int v, t, varg, is_vaargs, t0;
    int saved_parse_flags = parse_flags;
    TokenString str;
    v = tok;
    if (v < 256 || v == TOK_DEFINED)
        _tcc_error("invalid macro name '%s'", get_tok_str(tok, &tokc));
    first = ((void*)0);
    t = 0;
    parse_flags = ((parse_flags & ~0x0008) | 0x0010);
    next_nomacro();
    parse_flags &= ~0x0010;
