            goto unary_result;
        case 0x94:
            i = f1 == f2;
	make_int:
            vtop -= 2;
            vpushi(i);
            return;
        case 0x95:
            i = f1 != f2;
	    goto make_int;
        case 0x9c:
            i = f1 < f2;
	    goto make_int;
        case 0x9d:
            i = f1 >= f2;
	    goto make_int;
        case 0x9e:
            i = f1 <= f2;
	    goto make_int;
        case 0x9f:
            i = f1 > f2;
	    goto make_int;
        default:
            goto general_case;
