static void skip_or_save_block(TokenString **str)
{
    int braces = tok == '{';
    int level = 0;
    if (str)
      *str = tok_str_alloc();
    while (1) {
	int t = tok;
        if (level == 0
            && (t == ','
             || t == ';'
             || t == '}'
             || t == ')'
             || t == ']'))
             break;
	if (t == (-1)) {
	     if (str || level > 0)
	       _tcc_error("unexpected end of file");
	     else
	       break;
	}
	if (str)
	  tok_str_add_tok(*str);
	next();
	if (t == '{' || t == '(' || t == '[') {
	    level++;
	} else if (t == '}' || t == ')' || t == ']') {
	    level--;
	    if (level == 0 && braces && t == '}')
	      break;
	}
    }
    if (str)
	tok_str_add(*str, (-1));
}
static void parse_init_elem(int expr_type)
{
    int saved_global_expr;
    switch(expr_type) {
    case 1:
        saved_global_expr = global_expr;
        global_expr = 1;
        expr_const1();
        global_expr = saved_global_expr;
        if (((vtop->r & (0x003f | 0x0100)) != 0x0030
             && ((vtop->r & (0x0200|0x0100)) != (0x0200|0x0100)
                 || vtop->sym->v < 0x10000000))
                 || ((vtop->r & 0x0200) && vtop->sym->a.dllimport)
           )
            _tcc_error("initializer element is not constant");
        break;
    case 2:
        expr_eq();
        break;
    }
}
static void init_assert(init_params *p, int offset)
{
    if (p->sec ? !(nocode_wanted > 0) && offset > p->sec->data_offset
               : !nocode_wanted && offset > p->local_offset)
        _tcc_error("internal compiler error in %s:%d: %s", __FUNCTION__,7652,"initializer overflow");
}
static void init_putz(init_params *p, unsigned long c, int size)
{
    init_assert(p, c + size);
    if (p->sec) {
    } else {
        vpush_helper_func(TOK_memset);
        vseti(0x0032, c);
        vpushi(0);
        vpushs(size);
        gfunc_call(3);
    }
}
static void decl_design_delrels(Section *sec, int c, int size)
{
    Elf64_Rela *rel, *rel2, *rel_end;
    if (!sec || !sec->reloc)
        return;
    rel = rel2 = (Elf64_Rela*)sec->reloc->data;
    rel_end = (Elf64_Rela*)(sec->reloc->data + sec->reloc->data_offset);
    while (rel < rel_end) {
        if (rel->r_offset >= c && rel->r_offset < c + size) {
            sec->reloc->data_offset -= sizeof *rel;
        } else {
            if (rel2 != rel)
                memcpy(rel2, rel, sizeof *rel);
            ++rel2;
        }
        ++rel;
    }
}
static void decl_design_flex(init_params *p, Sym *ref, int index)
{
    if (ref == p->flex_array_ref) {
        if (index >= ref->c)
            ref->c = index + 1;
    } else if (ref->c < 0 && index >= 0)
        _tcc_error("flexible array has zero size in this context");
}
