    tcc_state->cur_text_section->data_offset = ind;
    sym_pop(&local_stack, ((void*)0), 0);
    label_pop(&global_label_stack, ((void*)0), 0);
    sym_pop(&all_cleanups, ((void*)0), 0);
    local_scope = 0;
    tcc_state->cur_text_section = ((void*)0);
    funcname = "";
