static int put_stabs(TCCState *s1, const char *str, int type, int other,
    int desc, unsigned long value);
static void tcc_debug_new(TCCState *s1)
{
    int shf = 0;
    if (!s1->dState)
        s1->dState = tcc_mallocz(sizeof *s1->dState);
    if (s1->dwarf) {
	int i;
	static const char *const debug[] = {
	    ".debug_macro",
	    ".debug_loc",
	    ".debug_ranges",
	    ".debug_loclists",
	    ".debug_rnglists",
	    ".debug_str_offsets",
	    ".debug_addr"
	};
        s1->dwlo = s1->nb_sections;
        s1->dwarf_info_section =
	    new_section(s1, ".debug_info", 1, shf);
        s1->dwarf_abbrev_section =
	    new_section(s1, ".debug_abbrev", 1, shf);
        s1->dwarf_line_section =
	    new_section(s1, ".debug_line", 1, shf);
        s1->dwarf_aranges_section =
	    new_section(s1, ".debug_aranges", 1, shf);
	for (i = 0; i < sizeof(debug)/sizeof(debug[0]); i++)
	    new_section(s1, debug[i], 1, 0)->sh_addralign = 1;
	shf |= (1 << 4) | (1 << 5);
        s1->dwarf_str_section =
	    new_section(s1, ".debug_str", 1, shf);
	s1->dwarf_str_section->sh_entsize = 1;
	s1->dwarf_info_section->sh_addralign =
	s1->dwarf_abbrev_section->sh_addralign =
	s1->dwarf_line_section->sh_addralign =
	s1->dwarf_aranges_section->sh_addralign =
	s1->dwarf_str_section->sh_addralign = 1;
	if (s1->dwarf >= 5) {
            s1->dwarf_line_str_section =
	        new_section(s1, ".debug_line_str", 1, shf);
	    s1->dwarf_line_str_section->sh_entsize = 1;
	    s1->dwarf_line_str_section->sh_addralign = 1;
	}
        s1->dwhi = s1->nb_sections;
    }
    else
    {
        s1->stab_section = new_section(s1, ".stab", 1, shf);
        s1->stab_section->sh_entsize = sizeof(Stab_Sym);
        s1->stab_section->sh_addralign = sizeof ((Stab_Sym*)0)->n_value;
        s1->stab_section->link = new_section(s1, ".stabstr", 3, shf);
        put_stabs(s1, "", 0, 0, 0, 0);
    }
}
static int put_stabs(TCCState *s1, const char *str, int type, int other, int desc,
                      unsigned long value)
{
    Stab_Sym *sym;
    unsigned offset;
    if (type == N_SLINE
        && (offset = s1->stab_section->data_offset)
        && (sym = (Stab_Sym*)(s1->stab_section->data + offset) - 1)
        && sym->n_type == type
        && sym->n_value == value) {
        sym->n_desc = desc;
        return 0;
    }
    sym = section_ptr_add(s1->stab_section, sizeof(Stab_Sym));
    if (str) {
        sym->n_strx = put_elf_str(s1->stab_section->link, str);
    } else {
        sym->n_strx = 0;
    }
    sym->n_type = type;
    sym->n_other = other;
    sym->n_desc = desc;
    sym->n_value = value;
    return 1;
}
static void put_stabs_r(TCCState *s1, const char *str, int type, int other, int desc,
                        unsigned long value, Section *sec, int sym_index)
{
    if (put_stabs(s1, str, type, other, desc, value))
        put_elf_reloc(s1->symtab_section, s1->stab_section,
                      s1->stab_section->data_offset - 4,
                      sizeof ((Stab_Sym*)0)->n_value == 8 ? 1 : 11,
                      sym_index);
}
static void put_stabn(TCCState *s1, int type, int other, int desc, int value)
{
    put_stabs(s1, ((void*)0), type, other, desc, value);
}
static int dwarf_get_section_sym(Section *s)
{
    TCCState *s1 = s->s1;
    return put_elf_sym(s1->symtab_section, 0, 0,
                       ((((0)) << 4) + (((3)) & 0xf)), 0,
                       s->sh_num, ((void*)0));
}
static void dwarf_reloc(Section *s, int sym, int rel)
{
    TCCState *s1 = s->s1;
    put_elf_reloca(s1->symtab_section, s, s->data_offset, rel, sym, 0);
}
static void free_str(struct dwarf_str_hash **str)
{
    int i;
    for (i = 0; i < (251); i++) {
       while (str[i]) {
           struct dwarf_str_hash *next = str[i]->next;
           tcc_free(str[i]);
           str[i] = next;
       }
    }
}
static unsigned str_hash(const char *s)
{
    unsigned h = 5381;
    while (*s)
       h += (*s++ & 0xffu) + h * 31;
    return h;
}
static void dwarf_string(Section *s, Section *dw, int sym, const char *str)
{
    TCCState *s1 = s->s1;
    int len, hash = str_hash(str) % (251);
    char *ptr;
    struct dwarf_str_hash *new_hash;
    struct dwarf_str_hash **dw_hash =
	dw == s1->dwarf_str_section ? s1->dState->dwarf_str : s1->dState->dwarf_line_str;
    len = strlen(str) + 1;
    new_hash = dw_hash[hash];
    while (new_hash) {
	if (new_hash->len == len &&
	    !memcmp(str, dw->data + new_hash->data_offset, len))
	    break;
	new_hash = new_hash->next;
    }
    if (new_hash == ((void*)0)) {
	unsigned long offset = dw->data_offset;
        new_hash = dw_hash[hash];
        while (new_hash) {
	    unsigned long n = new_hash->data_offset + new_hash->len - len;
	    if (new_hash->len > len &&
	        !memcmp(str, dw->data + n, len)) {
		offset = n;
		break;
	    }
	    new_hash = new_hash->next;
        }
	if (new_hash == ((void*)0)) {
	    ptr = section_ptr_add(dw, len);
	    memmove(ptr, str, len);
	}
	new_hash = (struct dwarf_str_hash *)
	    tcc_malloc(sizeof(struct dwarf_str_hash));
	new_hash->len = len;
	new_hash->data_offset = offset;
	new_hash->next = dw_hash[hash];
	dw_hash[hash] = new_hash;
    }
    put_elf_reloca(s1->symtab_section, s, s->data_offset, 10, sym,
                   8 == 4 ? 0 : new_hash->data_offset);
    write32le(section_ptr_add((s), 4), (8 == 4 ? new_hash->data_offset : 0));
}
static void dwarf_strp(Section *s, const char *str)
{
    TCCState *s1 = s->s1;
    dwarf_string(s, s1->dwarf_str_section, s1->dState->dwarf_sym.str, str);
}
static void dwarf_line_strp(Section *s, const char *str)
{
    TCCState *s1 = s->s1;
    dwarf_string(s, s1->dwarf_line_str_section, s1->dState->dwarf_sym.line_str, str);
}
static void dwarf_line_op(TCCState *s1, unsigned char op)
{
    if (s1->dState->dwarf_line.line_size >= s1->dState->dwarf_line.line_max_size) {
	s1->dState->dwarf_line.line_max_size += 1024;
	s1->dState->dwarf_line.line_data =
	    (unsigned char *)tcc_realloc(s1->dState->dwarf_line.line_data,
					 s1->dState->dwarf_line.line_max_size);
    }
    s1->dState->dwarf_line.line_data[s1->dState->dwarf_line.line_size++] = op;
}
static void dwarf_file(TCCState *s1)
{
    int i, j;
    char *filename;
    int index_offset = s1->dwarf < 5;
    if (!strcmp(file->filename, "<command line>")) {
        s1->dState->dwarf_line.cur_file = 1;
	return;
    }
    filename = strrchr(file->filename, '/');
    if (filename == ((void*)0)) {
        for (i = 1; i < s1->dState->dwarf_line.filename_size; i++)
            if (s1->dState->dwarf_line.filename_table[i].dir_entry == 0 &&
		strcmp(s1->dState->dwarf_line.filename_table[i].name,
		       file->filename) == 0) {
		    s1->dState->dwarf_line.cur_file = i + index_offset;
	            return;
		}
	i = -index_offset;
	filename = file->filename;
    }
    else {
	char *undo = filename;
	char *dir = file->filename;
	*filename++ = '\0';
        for (i = 0; i < s1->dState->dwarf_line.dir_size; i++)
	    if (strcmp(s1->dState->dwarf_line.dir_table[i], dir) == 0) {
		for (j = 1; j < s1->dState->dwarf_line.filename_size; j++)
		    if (s1->dState->dwarf_line.filename_table[j].dir_entry - index_offset
			== i &&
			strcmp(s1->dState->dwarf_line.filename_table[j].name,
			       filename) == 0) {
			*undo = '/';
		        s1->dState->dwarf_line.cur_file = j + index_offset;
			return;
		    }
		break;
	    }
	if (i == s1->dState->dwarf_line.dir_size) {
	    s1->dState->dwarf_line.dir_size++;
	    s1->dState->dwarf_line.dir_table =
                (char **) tcc_realloc(s1->dState->dwarf_line.dir_table,
                                      s1->dState->dwarf_line.dir_size *
                                      sizeof (char *));
            s1->dState->dwarf_line.dir_table[i] = tcc_strdup(dir);
	}
	*undo = '/';
    }
    s1->dState->dwarf_line.filename_table =
        (struct dwarf_filename_struct *)
        tcc_realloc(s1->dState->dwarf_line.filename_table,
                    (s1->dState->dwarf_line.filename_size + 1) *
                    sizeof (struct dwarf_filename_struct));
    s1->dState->dwarf_line.filename_table[s1->dState->dwarf_line.filename_size].dir_entry =
	i + index_offset;
    s1->dState->dwarf_line.filename_table[s1->dState->dwarf_line.filename_size].name =
        tcc_strdup(filename);
    s1->dState->dwarf_line.cur_file = s1->dState->dwarf_line.filename_size++ + index_offset;
    return;
}
static int dwarf_sleb128_size (long long value)
{
    int size =  0;
    long long end = value >> 63;
    unsigned char last = end & 0x40;
    unsigned char byte;
    do {
        byte = value & 0x7f;
        value >>= 7;
        size++;
    } while (value != end || (byte & 0x40) != last);
    return size;
}
static void dwarf_uleb128 (Section *s, unsigned long long value)
{
    do {
        unsigned char byte = value & 0x7f;
        value >>= 7;
        (*(uint8_t*)section_ptr_add((s), 1) = (byte | (value ? 0x80 : 0)));
    } while (value != 0);
}
static void dwarf_sleb128 (Section *s, long long value)
{
    int more;
    long long end = value >> 63;
    unsigned char last = end & 0x40;
    do {
        unsigned char byte = value & 0x7f;
        value >>= 7;
	more = value != end || (byte & 0x40) != last;
        (*(uint8_t*)section_ptr_add((s), 1) = (byte | (0x80 * more)));
    } while (more);
}
static void dwarf_uleb128_op (TCCState *s1, unsigned long long value)
{
    do {
        unsigned char byte = value & 0x7f;
        value >>= 7;
        dwarf_line_op(s1, byte | (value ? 0x80 : 0));
    } while (value != 0);
}
static void dwarf_sleb128_op (TCCState *s1, long long value)
{
    int more;
    long long end = value >> 63;
    unsigned char last = end & 0x40;
    do {
        unsigned char byte = value & 0x7f;
        value >>= 7;
        more = value != end || (byte & 0x40) != last;
        dwarf_line_op(s1, byte | (0x80 * more));
    } while (more);
}
