	ptr = s1->dwarf_info_section->data + s1->dState->dwarf_info.start;
	write32le(ptr, s1->dwarf_info_section->data_offset - s1->dState->dwarf_info.start - 4);
	write32le(ptr + 25 + (s1->dwarf >= 5) + 8, text_size);
