            for (i = cur->n_sym - 1; i >= 0; i--) {
                struct debug_sym *s = &cur->sym[i];
		(*(uint8_t*)section_ptr_add((s1->dwarf_info_section), 1) = (s->type == N_PSYM ? 6 : s->type == N_GSYM ? 3 : s->type == N_STSYM ? 4 : 5));
                dwarf_strp(s1->dwarf_info_section, s->str);
		if (s->type == N_GSYM || s->type == N_STSYM) {
                    dwarf_uleb128(s1->dwarf_info_section, s->file);
                    dwarf_uleb128(s1->dwarf_info_section, s->line);
		}
                write32le(section_ptr_add((s1->dwarf_info_section), 4), (s->info - s1->dState->dwarf_info.start));
		if (s->type == N_GSYM || s->type == N_STSYM) {
		    if (s->type == N_GSYM)
                        (*(uint8_t*)section_ptr_add((s1->dwarf_info_section), 1) = (1));
                    (*(uint8_t*)section_ptr_add((s1->dwarf_info_section), 1) = (8 + 1));
                    (*(uint8_t*)section_ptr_add((s1->dwarf_info_section), 1) = (DW_OP_addr));
		    if (s->type == N_STSYM)
		        dwarf_reloc(s1->dwarf_info_section, s1->dState->section_sym, 1);
                    write64le(section_ptr_add((s1->dwarf_info_section), 8), (s->value));
		}
		else {
                    (*(uint8_t*)section_ptr_add((s1->dwarf_info_section), 1) = (dwarf_sleb128_size((long)s->value) + 1));
                    (*(uint8_t*)section_ptr_add((s1->dwarf_info_section), 1) = (DW_OP_fbreg));
                    dwarf_sleb128(s1->dwarf_info_section, (long)s->value);
		}
		tcc_free (s->str);
            }
            tcc_free (cur->sym);
            (*(uint8_t*)section_ptr_add((s1->dwarf_info_section), 1) = (cur->child ? 22 : 23));
            dwarf_reloc(s1->dwarf_info_section, s1->dState->section_sym, 1);
            write64le(section_ptr_add((s1->dwarf_info_section), 8), (func_ind + cur->start));
            write64le(section_ptr_add((s1->dwarf_info_section), 8), (cur->end - cur->start));
            tcc_debug_finish (s1, cur->child);
