static void gen_expr32(ExprValue *pe)
{
    if (pe->pcrel)
	gen_addrpc32(0x0200, pe->sym, pe->v + (ind + 4));
    else
	gen_addr32(pe->sym ? 0x0200 : 0, pe->sym, pe->v);
}
static void gen_disp32(ExprValue *pe)
{
    Sym *sym = pe->sym;
    Elf64_Sym *esym = elfsym(sym);
    if (esym && esym->st_shndx == tcc_state->cur_text_section->sh_num) {
        gen_le32(pe->v + esym->st_value - ind - 4);
    } else {
        if (sym && sym->type.t == 0) {
            sym->type.t = 6;
            sym->type.ref = ((void*)0);
        }
        greloca(tcc_state->cur_text_section, sym, ind, 4, pe->v - 4);
        gen_le32(0);
    }
}
static __inline int asm_modrm(int reg, Operand *op)
{
    int mod, reg1, reg2, sib_reg1;
    if (op->type & (((1 << OPT_REG8) | (1 << OPT_REG16) | (1 << OPT_REG32) | (1 << OPT_REG64)) | (1 << OPT_MMX) | (1 << OPT_SSE))) {
        g(0xc0 + (reg << 3) + op->reg);
    } else if (op->reg == -1 && op->reg2 == -1) {
	g(0x04 + (reg << 3));
	g(0x25);
	gen_expr32(&op->e);
    } else if (op->reg == -2) {
        ExprValue *pe = &op->e;
        g(0x05 + (reg << 3));
        gen_addrpc32(pe->sym ? 0x0200 : 0, pe->sym, pe->v);
        return ind;
    } else {
        sib_reg1 = op->reg;
        if (sib_reg1 == -1) {
            sib_reg1 = 5;
            mod = 0x00;
        } else if (op->e.v == 0 && !op->e.sym && op->reg != 5) {
            mod = 0x00;
        } else if (op->e.v == (int8_t)op->e.v && !op->e.sym) {
            mod = 0x40;
        } else {
            mod = 0x80;
        }
        reg1 = op->reg;
        if (op->reg2 != -1)
            reg1 = 4;
        g(mod + (reg << 3) + reg1);
        if (reg1 == 4) {
            reg2 = op->reg2;
            if (reg2 == -1)
                reg2 = 4;
            g((op->shift << 6) + (reg2 << 3) + sib_reg1);
        }
        if (mod == 0x40) {
            g(op->e.v);
        } else if (mod == 0x80 || op->reg == -1) {
	    gen_expr32(&op->e);
        }
    }
    return 0;
}
static void asm_rex(int width64, Operand *ops, int nb_ops, int *op_type,
		    int regi, int rmi)
{
  unsigned char rex = width64 ? 0x48 : 0;
  int saw_high_8bit = 0;
  int i;
  if (rmi == -1) {
      for(i = 0; i < nb_ops; i++) {
	  if (op_type[i] & (((1 << OPT_REG8) | (1 << OPT_REG16) | (1 << OPT_REG32) | (1 << OPT_REG64)) | (1 << OPT_ST))) {
	      if (ops[i].reg >= 8) {
		  rex |= 0x41;
		  ops[i].reg -= 8;
	      } else if (ops[i].type & (1 << OPT_REG8_LOW))
		  rex |= 0x40;
	      else if (ops[i].type & (1 << OPT_REG8) && ops[i].reg >= 4)
		  saw_high_8bit = ops[i].reg;
	      break;
	  }
      }
  } else {
      if (regi != -1) {
	  if (ops[regi].reg >= 8) {
	      rex |= 0x44;
	      ops[regi].reg -= 8;
	  } else if (ops[regi].type & (1 << OPT_REG8_LOW))
	      rex |= 0x40;
	  else if (ops[regi].type & (1 << OPT_REG8) && ops[regi].reg >= 4)
	      saw_high_8bit = ops[regi].reg;
      }
      if (ops[rmi].type & (((1 << OPT_REG8) | (1 << OPT_REG16) | (1 << OPT_REG32) | (1 << OPT_REG64)) | (1 << OPT_MMX) | (1 << OPT_SSE) | (1 << OPT_CR) | 0x40000000u)) {
	  if (ops[rmi].reg >= 8) {
	      rex |= 0x41;
	      ops[rmi].reg -= 8;
	  } else if (ops[rmi].type & (1 << OPT_REG8_LOW))
	      rex |= 0x40;
	  else if (ops[rmi].type & (1 << OPT_REG8) && ops[rmi].reg >= 4)
	      saw_high_8bit = ops[rmi].reg;
      }
      if (ops[rmi].type & 0x40000000u && ops[rmi].reg2 >= 8) {
	  rex |= 0x42;
	  ops[rmi].reg2 -= 8;
      }
  }
  if (rex) {
      if (saw_high_8bit)
	  _tcc_error("can't encode register %%%ch when REX prefix is required",
		    "acdb"[saw_high_8bit-4]);
      g(rex);
  }
}
static void maybe_print_stats (void)
{
    static int already;
    if (0 && !already)
    {
        const struct ASMInstr *pa;
        int freq[4];
        int op_vals[500];
        int nb_op_vals, i, j;
	already = 1;
        nb_op_vals = 0;
        memset(freq, 0, sizeof(freq));
        for(pa = asm_instrs; pa->sym != 0; pa++) {
            freq[pa->nb_ops]++;
                for(j=0;j<nb_op_vals;j++) {
                    if (pa->instr_type == op_vals[j])
                        goto found;
                }
                op_vals[nb_op_vals++] = pa->instr_type;
            found: ;
        }
        for(i=0;i<nb_op_vals;i++) {
            int v = op_vals[i];
                printf("%3d: %08x\n", i, v);
        }
        printf("size=%d nb=%d f0=%d f1=%d f2=%d f3=%d\n",
               (int)sizeof(asm_instrs),
	       (int)sizeof(asm_instrs) / (int)sizeof(ASMInstr),
               freq[0], freq[1], freq[2], freq[3]);
    }
}
