        if (flags & (1 << 10))
            return sec_tdata + (type == 8);
        if (type == 1
         || type == 14
         || type == 15) {
            if (flags & (1 << 2))
                return sec_text;
            if (flags & (1 << 0))
                return sec_data;
            if (0 == strcmp(name, ".rsrc"))
                return sec_rsrc;
            if (0 == strcmp(name, ".iedat"))
                return sec_idata;
            if (0 == strcmp(name, ".pdata"))
                return sec_pdata;
            return sec_rdata;
        } else if (type == 8) {
            return sec_bss;
        }
        return sec_other;
