static char *quote_win32(const char *s)
{
    char *o, *r = tcc_malloc(2 * strlen(s) + 3);
    int cbs = 0, quoted = !*s;
    for (o = r; *s; *o++ = *s++) {
        quoted |= *s == ' ' || *s == '\t';
        if (*s == '\\' || *s == '"')
            *o++ = '\\';
        else
            o -= cbs;
        cbs = *s == '\\' ? cbs + 1 : 0;
    }
    if (quoted) {
        memmove(r + 1, r, o++ - r);
        *r = *o++ = '"';
    } else {
        o -= cbs;
    }
    *o = 0;
    return r;
}
static int execvp_win32(const char *prog, char **argv)
{
    int ret; char **p;
    for (p = argv; *p; ++p)
        *p = quote_win32(*p);
    ret = _spawnvp(1, prog, (const char *const*)argv);
    if (-1 == ret)
        return ret;
    _cwait(&ret, ret, 0);
    exit(ret);
}
static int tcc_tool_cross(char **argv, int target)
{
    char program[4096];
    char *a0 = argv[0];
    int prefix = tcc_basename(a0) - a0;
    _snprintf(program, sizeof program,
        "%.*s%s"
        "-win32"
        "-tcc"
        ".exe"
        , prefix, a0, target == 64 ? "x86_64" : "i386");
    if (strcmp(a0, program))
        execvp_win32(argv[0] = program, argv);
    fprintf((&__iob_func()[2]), "tcc: could not run '%s'\n", program);
    return 1;
}
